script:
frappe.ui.form.on("Job Card", {
    setup(frm) {
        frm.set_query("assigned_technician", function () {
            return {
                filters: {
                    status: "Active",
                    specialization: frm.doc.device_type
                }
            };
        });
    },

    refresh(frm) {
        frm.dashboard.clear_headline();

        const indicators = {
            "Draft": "orange",
            "Pending Diagnosis": "orange",
            "Awaiting Customer Approval": "yellow",
            "In Repair": "blue",
            "Ready for Delivery": "green",
            "Delivered": "green",
            "Cancelled": "red"
        };

        if (frm.doc.status && indicators[frm.doc.status]) {
            frm.dashboard.add_indicator(
                frm.doc.status,
                indicators[frm.doc.status]
            );
        }

        if (
            frm.doc.status === "Ready for Delivery" &&
            frm.doc.docstatus === 1
        ) {
            frm.add_custom_button("Mark as Delivered", function () {
                frm.set_value("status", "Delivered");
                frm.save();
            });
        }

        if (!frm.is_new()) {
            frm.add_custom_button("Reject Job", function () {
                show_reject_dialog(frm);
            });
        }

        if (!frm.is_new()) {
            frm.add_custom_button("Transfer Technician", function () {
                transfer_technician(frm);
            });
        }
    },

    assigned_technician(frm) {
        if (
            !frm.doc.assigned_technician ||
            !frm.doc.device_type
        ) {
            return;
        }

        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Technician",
                name: frm.doc.assigned_technician
            },
            callback: function (r) {
                if (!r.message) {
                    return;
                }

                const technician = r.message;

                if (
                    technician.specialization &&
                    technician.specialization !== frm.doc.device_type
                ) {
                    frappe.msgprint({
                        title: "Technician Mismatch",
                        message:
                            `Technician specialization is ` +
                            `<b>${technician.specialization}</b>, ` +
                            `but this Job Card is for ` +
                            `<b>${frm.doc.device_type}</b>.`,
                        indicator: "orange"
                    });
                }
            }
        });
    }
});


frappe.ui.form.on("Part Usage Entry", {
    quantity(frm, cdt, cdn) {
        calculate_part_total(cdt, cdn);
    },
});


function calculate_part_total(cdt, cdn) {
    const row = locals[cdt][cdn];

    const quantity = flt(row.quantity);
    const unit_price = flt(row.unit_price);

    const total_price = quantity * unit_price;

    frappe.model.set_value(
        cdt,
        cdn,
        "total_price",
        total_price
    );
}


function show_reject_dialog(frm) {
    const dialog = new frappe.ui.Dialog({
        title: "Reject Job",

        fields: [
            {
                label: "Rejection Reason",
                fieldname: "rejection_reason",
                fieldtype: "Small Text",
                reqd: 1
            }
        ],

        primary_action_label: "Reject",

        primary_action(values) {
            frm.set_value(
                "status",
                "Cancelled"
            );

            frm.set_value(
                "remarks",
                values.rejection_reason
            );

            dialog.hide();

            frm.save();
        }
    });

    dialog.show();
}


function transfer_technician(frm) {
    frappe.prompt(
        [
            {
                label: "New Technician",
                fieldname: "technician",
                fieldtype: "Link",
                options: "Technician",
                reqd: 1
            }
        ],

        function (values) {
            const new_technician = values.technician;

            frappe.confirm(
                `Transfer this Job Card to ` +
                `<b>${new_technician}</b>?`,

                function () {
                    frappe.call({
                        method: "frappe.client.set_value",

                        args: {
                            doctype: "Job Card",
                            name: frm.doc.name,
                            fieldname: "assigned_technician",
                            value: new_technician
                        },

                        callback: function (r) {
                            if (!r.exc) {
                                frm.reload_doc();

                                frm.trigger(
                                    "assigned_technician"
                                );
                            }
                        }
                    });
                }
            );
        },

        "Transfer Technician",
        "Transfer"
    );
}

frappe.ui.form.on("Job Card", {
    refresh(frm) {
        if (frappe.user_roles.includes("QF Manager")) {
            frm.set_df_property("customer_phone", "hidden", 0);
        } else {
            frm.set_df_property("customer_phone", "hidden", 1);
        }
    }
});
